import{_ as i,o as t,c as a,a0 as r}from"./chunks/framework.DScjKhBS.js";const g=JSON.parse('{"title":"PR design and work slicing patterns","description":"Change-shaping patterns that preserve reviewability when deep reviewer capacity is scarce.","frontmatter":{"title":"PR design and work slicing patterns","description":"Change-shaping patterns that preserve reviewability when deep reviewer capacity is scarce."},"headers":[],"relativePath":"reports/pr-review-continuity/04-pr-design-and-work-slicing-patterns.md","filePath":"reports/pr-review-continuity/04-pr-design-and-work-slicing-patterns.md"}'),n={name:"reports/pr-review-continuity/04-pr-design-and-work-slicing-patterns.md"};function s(o,e,l,c,d,p){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="pr-design-and-work-slicing-patterns" tabindex="-1">PR design and work slicing patterns <a class="header-anchor" href="#pr-design-and-work-slicing-patterns" aria-label="Permalink to &quot;PR design and work slicing patterns&quot;">​</a></h1><h2 id="target-single-purpose-single-session-reviewable-changes" tabindex="-1">Target: single-purpose, single-session reviewable changes <a class="header-anchor" href="#target-single-purpose-single-session-reviewable-changes" aria-label="Permalink to &quot;Target: single-purpose, single-session reviewable changes&quot;">​</a></h2><p>Large mixed-purpose PRs are the fastest route to shallow approval. Use stackable, narrow PRs that each answer one question.</p><hr><h2 id="recommended-slicing-sequence" tabindex="-1">Recommended slicing sequence <a class="header-anchor" href="#recommended-slicing-sequence" aria-label="Permalink to &quot;Recommended slicing sequence&quot;">​</a></h2><p>For medium/high-complexity work, split in this order:</p><ol><li><strong>Preparation PR</strong> (renames, extraction, no behavior change)</li><li><strong>Behavior PR</strong> (minimal functional delta)</li><li><strong>Validation PR</strong> (tests, fixtures, monitoring hooks)</li><li><strong>Cleanup PR</strong> (debt removal, docs updates)</li></ol><p>This pattern lowers cognitive load and improves defect localization.</p><hr><h2 id="anti-patterns-to-ban-during-constrained-periods" tabindex="-1">Anti-patterns to ban during constrained periods <a class="header-anchor" href="#anti-patterns-to-ban-during-constrained-periods" aria-label="Permalink to &quot;Anti-patterns to ban during constrained periods&quot;">​</a></h2><ul><li>&quot;Refactor + feature + test + docs&quot; in one PR</li><li>Cross-cutting mechanical changes mixed with behavior changes</li><li>Massive AI-generated rewrites without rationale and checkpoints</li><li>&quot;Will explain in Slack&quot; instead of explicit PR narrative</li></ul><hr><h2 id="reviewability-checklist-author-side" tabindex="-1">Reviewability checklist (author-side) <a class="header-anchor" href="#reviewability-checklist-author-side" aria-label="Permalink to &quot;Reviewability checklist (author-side)&quot;">​</a></h2><p>Before requesting review:</p><ul><li>Can a reviewer explain the intent in one sentence?</li><li>Is there a clear map of touched subsystems?</li><li>Are high-risk paths isolated and highlighted?</li><li>Are test additions proving behavior, not just increasing line count?</li><li>Is rollback safe and documented?</li></ul><p>If not, split again.</p><hr><h2 id="practical-templates" tabindex="-1">Practical templates <a class="header-anchor" href="#practical-templates" aria-label="Permalink to &quot;Practical templates&quot;">​</a></h2><p>Use short templates to reduce ambiguity:</p><ul><li><strong>PR title format:</strong> <code>&lt;type&gt;: &lt;scope&gt; — &lt;intent&gt;</code></li><li><strong>Top-of-PR summary:</strong> <code>Context / Change / Risk / Evidence / Rollback</code></li><li><strong>File review order:</strong> &quot;Read these files first, then these&quot;</li></ul><p>These reduce reviewer startup overhead and improve consistency across reviewers.</p><hr><p><strong>Next:</strong> <a href="./reports/pr-review-continuity/05-ai-assisted-review-without-blind-trust.html">AI-assisted review without blind trust</a></p>',23)])])}const u=i(n,[["render",s]]);export{g as __pageData,u as default};
